package dev.astralreach.hytale;
import com.hypixel.hytale.codec.*;import com.hypixel.hytale.codec.builder.BuilderCodec;import com.hypixel.hytale.component.Component;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import org.bson.*;import dev.astralreach.core.ExpeditionPerks;import dev.astralreach.core.BlueprintExpedition;import java.util.*;
/** Per-player discoveries and one-time archive recovery survive ordinary save/load. */
public final class FieldJournal implements Component<EntityStore>{
 String selectedSite="",selectedMission="survey";
 final Set<String>discovered=new HashSet<>(),claimed=new HashSet<>(),perks=new HashSet<>(),blueprintRecords=new HashSet<>(),blueprints=new HashSet<>(),blueprintDiscoveries=new HashSet<>();
 public static final BuilderCodec<FieldJournal>CODEC=BuilderCodec.builder(FieldJournal.class,FieldJournal::new).append(new KeyedCodec<>("JournalV1",Codec.STRING),FieldJournal::restore,FieldJournal::snapshot).add().build();
 public FieldJournal(){}
 boolean reconcilePerks(){return ExpeditionPerks.reconcile(claimed,perks);}
 String snapshot(){reconcilePerks();BlueprintExpedition.reconcile(blueprintRecords,blueprints);var rewards=new BsonArray();perks.stream().sorted().forEach(x->rewards.add(new BsonString(x)));var d=new BsonArray();discovered.stream().sorted().forEach(x->d.add(new BsonString(x)));var c=new BsonArray();claimed.stream().sorted().forEach(x->c.add(new BsonString(x)));return new BsonDocument("Discovered",d).append("Claimed",c).append("Selected",new BsonString(selectedSite)).append("Perks",rewards).append("BlueprintRecords",array(blueprintRecords)).append("Blueprints",array(blueprints)).append("BlueprintDiscoveries",array(blueprintDiscoveries)).append("Mission",new BsonString(selectedMission)).toJson();}
 static BsonArray array(Set<String>values){var a=new BsonArray();values.stream().sorted().forEach(x->a.add(new BsonString(x)));return a;}
 void restore(String text){blueprintRecords.clear();blueprints.clear();blueprintDiscoveries.clear();selectedMission="survey";discovered.clear();claimed.clear();perks.clear();selectedSite="";if(text==null||text.isEmpty())return;var d=BsonDocument.parse(text);selectedSite=d.getString("Selected",new BsonString("")).getValue();if(!selectedSite.isEmpty()&&!selectedSite.matches("-?[0-9]+:-?[0-9]+:-?[0-9]+"))throw new IllegalArgumentException("Invalid selected survey site");for(var v:d.getArray("Discovered"))discovered.add(v.asString().getValue());for(var v:d.getArray("Claimed"))claimed.add(v.asString().getValue());for(var v:d.getArray("Perks",new BsonArray())){String id=v.asString().getValue();if(!id.matches("[a-z0-9_]{1,64}"))throw new IllegalArgumentException("Invalid expedition perk ID");perks.add(id);}for(var v:d.getArray("BlueprintRecords",new BsonArray()))blueprintRecords.add(v.asString().getValue());for(var v:d.getArray("BlueprintDiscoveries",new BsonArray()))blueprintDiscoveries.add(v.asString().getValue());for(var v:d.getArray("Blueprints",new BsonArray())){String id=v.asString().getValue();if(!id.matches("[a-z0-9_]{1,64}"))throw new IllegalArgumentException("Invalid blueprint ID");blueprints.add(id);}selectedMission=d.getString("Mission",new BsonString("survey")).getValue();if(!selectedMission.equals("survey")){try{BlueprintExpedition.Kind.from(selectedMission);}catch(IllegalArgumentException ignored){selectedMission="survey";}}BlueprintExpedition.reconcile(blueprintRecords,blueprints);reconcilePerks();}
 @Override public Component<EntityStore>clone(){var j=new FieldJournal();j.restore(snapshot());return j;}
}
